package io.github.jesterportfolio.hearth.quest;

import io.github.jesterportfolio.hearth.story.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.exploration.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class SharedStoryTest {
    static Map<String,Object> stage(String id,String next){var m=new HashMap<String,Object>();m.put("id",id);m.put("title","공개 "+id);m.put("next-goal","공개 목표 "+id);m.put("entry",List.of("survey_marker"));m.put("complete",List.of("survey_marker"));if(next!=null)m.put("next",next);return m;}
    static Map<String,Object> root(){var a=stage("arrival","vote");var b=stage("vote",null);b.put("complete",List.of("path_marker"));b.put("choices",List.of(Map.of("id","one","label","공개 하나","next","open"),Map.of("id","two","label","공개 둘","next","open")));var c=stage("open",null);c.put("entry",List.of("path_marker"));c.put("complete",List.of("path_marker"));c.put("opens-exploration",true);
        return new HashMap<>(Map.of("format",1,"first","arrival","stages",List.of(a,b,c),"regions",List.of(Map.of("id","private_area","policy","ENTRY","requires-stage","open","bounds",Map.of("min-x",20,"max-x",22,"min-y",64,"max-y",67,"min-z",20,"max-z",22)))));}
    static StoryContent definitions(){return StoryContent.parse(root(),QuestCatalogTest.catalog(),ExplorationTest.content());}
    static StoryStore.Snapshot empty(){return new StoryStore.Snapshot(new ExplorationStore.Story(null,null,null,-1),Set.of(),Map.of());}
    static final class Store implements StoryStore{
        final Map<UUID,Snapshot> snapshots=new HashMap<>();final Map<UUID,Set<UUID>> survey=new HashMap<>(),path=new HashMap<>();final Map<String,String> receipts=new HashMap<>();int commits;boolean delay,checkDelay,fail,unknown,unknownAfter;
        CompletableFuture<Map<UUID,Boolean>> conditions;CompletableFuture<Snapshot> write;Request request;BooleanSupplier fence;ServerProgressAccess.Context writing;
        public CompletionStage<Snapshot> readStory(ServerProgressAccess.Context c){return CompletableFuture.completedFuture(snapshots.getOrDefault(c.storyRunId(),empty()));}
        public CompletionStage<Map<UUID,Boolean>> storyConditions(ServerProgressAccess.Context c,Set<UUID> players,Set<String> required){var result=new HashMap<UUID,Boolean>();for(UUID p:players)result.put(p,(!required.contains("survey_marker")||survey.getOrDefault(c.storyRunId(),Set.of()).contains(p))&&(!required.contains("path_marker")||path.getOrDefault(c.storyRunId(),Set.of()).contains(p)));if(checkDelay){conditions=new CompletableFuture<>();return conditions;}return CompletableFuture.completedFuture(result);}
        public CompletionStage<Snapshot> commitStory(ServerProgressAccess.Context c,Request r,BooleanSupplier guard){commits++;request=r;writing=c;fence=guard;if(delay){write=new CompletableFuture<>();return write;}return save(c,r,guard);}
        CompletionStage<Snapshot> save(ServerProgressAccess.Context c,Request r,BooleanSupplier guard){if(fail)return CompletableFuture.failedFuture(new StorageFailure("story","23514"));if(!guard.getAsBoolean())return CompletableFuture.failedFuture(new StorageFailure("story","STALE_ROSTER"));if(unknown&&!unknownAfter)return CompletableFuture.failedFuture(new StorageFailure("story","COMMIT_UNKNOWN"));var old=snapshots.getOrDefault(c.storyRunId(),empty());if(old.story().revision()!=r.revision())return CompletableFuture.failedFuture(new StorageFailure("story","REVISION_CONFLICT"));var complete=new HashSet<>(old.completed());if(r.from()!=null)complete.add(r.from());var branches=new HashMap<>(old.branches());if(r.choice()!=null)branches.put(r.from(),new Branch(r.from(),r.choice(),r.label(),r.id()));var next=new Snapshot(new ExplorationStore.Story(r.to(),r.title(),r.open(),r.revision()+1),complete,branches);snapshots.put(c.storyRunId(),next);receipts.put(c.storyRunId()+"/"+r.id(),StoryStore.fingerprint(r));return unknown?CompletableFuture.failedFuture(new StorageFailure("story","COMMIT_UNKNOWN")):CompletableFuture.completedFuture(next);}
        void finish(){save(writing,request,fence).whenComplete((s,e)->{if(e==null)write.complete(s);else write.completeExceptionally(e);});}
        public CompletionStage<Optional<String>> storyReceipt(ServerProgressAccess.Context c,UUID id){return CompletableFuture.completedFuture(Optional.ofNullable(receipts.get(c.storyRunId()+"/"+id)));}
    }
    static final class F{
        final Store store=new Store();final ArrayDeque<Runnable> queue=new ArrayDeque<>();final ServerProgressAccess access=new ServerProgressAccess();final UUID a=UUID.randomUUID(),b=UUID.randomUUID(),p1=UUID.randomUUID(),p2=UUID.randomUUID();final Object t1=new Object(),t2=new Object();final Map<UUID,Object> roster=new HashMap<>();final AtomicLong time=new AtomicLong();final SharedStory story;final ServerProgressAccess.Context c=access.forVerifiedServerLink(a,p1),d=access.forVerifiedServerLink(b,p1);
        F(){roster.put(p1,t1);roster.put(p2,t2);story=new SharedStory(store,definitions(),queue::add,()->{},ctx->ctx.storyRunId().equals(a)?Map.copyOf(roster):Map.of(p1,t1),time::get,java.time.Duration.ofSeconds(30));ok(story.load(c));ok(story.load(d));}
        void pump(){int n=1000;while(!queue.isEmpty()){assertTrue(n-->0);queue.remove().run();}}
        <T>T ok(CompletionStage<T> f){pump();return f.toCompletableFuture().join();}
        void bad(CompletionStage<?> f){pump();assertTrue(f.toCompletableFuture().isCompletedExceptionally());}
        void survey(){store.survey.put(a,Set.of(p1,p2));store.survey.put(b,Set.of(p1));}
        void readyVote(){survey();ok(story.advance(c,t1,()->true));ok(story.advance(c,t1,()->true));store.path.put(a,Set.of(p1,p2));}
    }
    @Test void malformedGraphConditionsAndRegionReferencesAreRejected(){for(String defect:List.of("first","loop","condition","region")){var r=root();if(defect.equals("first"))r.put("first","missing");if(defect.equals("loop"))r.put("stages",List.of(stage("arrival","arrival")));if(defect.equals("condition")){var s=stage("arrival",null);s.put("entry",List.of("missing"));r.put("stages",List.of(s));}if(defect.equals("region"))r.put("regions",List.of(Map.of("id","missing","policy","OPEN","bounds",Map.of())));assertThrows(IllegalArgumentException.class,()->StoryContent.parse(r,QuestCatalogTest.catalog(),ExplorationTest.content()));}}
    @Test void allOnlineConditionsOneOfflineAndDuplicateAdvanceAreSafe(){var f=new F();f.store.survey.put(f.a,Set.of(f.p1));f.bad(f.story.advance(f.c,f.t1,()->true));assertNull(f.story.cached(f.a).story().stage());assertEquals(0,f.store.commits);
        f.roster.remove(f.p2);f.story.rosterChanged(f.c);f.store.delay=true;var first=f.story.advance(f.c,f.t1,()->true);f.pump();f.bad(f.story.advance(f.c,f.t1,()->true));assertFalse(first.toCompletableFuture().isDone());assertNull(f.story.cached(f.a).story().stage());f.store.finish();assertEquals("arrival",f.ok(first).story().stage());assertNull(f.story.cached(f.b).story().stage());}
    @Test void rosterChangeDuringCheckRejectsOldDecisionAndOldSession(){var f=new F();f.survey();f.store.checkDelay=true;var work=f.story.advance(f.c,f.t1,()->true);f.pump();f.roster.put(f.p1,new Object());f.story.rosterChanged(f.c);f.store.conditions.complete(Map.of(f.p1,true,f.p2,true));f.bad(work);assertEquals(0,f.store.commits);f.bad(f.story.advance(f.c,f.t1,()->true));}
    @Test void voteTieAbstainDeadlineAndSingleTargetMajority(){var f=new F();f.readyVote();var vote=f.ok(f.story.openVote(f.c,f.t1,()->true));assertEquals(30,vote.remainingSeconds());f.ok(f.story.cast(f.c,f.t1,()->true,vote.id(),"one"));f.ok(f.story.cast(f.access.forVerifiedServerLink(f.a,f.p2),f.t2,()->true,vote.id(),"two"));assertEquals("vote",f.story.cached(f.a).story().stage());f.time.set(30_000_000_000L);f.story.poll(f.c);assertEquals("UNDECIDED",f.story.vote(f.a).orElseThrow().state());
        f.roster.remove(f.p2);f.story.rosterChanged(f.c);var single=f.ok(f.story.openVote(f.c,f.t1,()->true));f.ok(f.story.cast(f.c,f.t1,()->true,single.id(),"abstain"));assertEquals("vote",f.story.cached(f.a).story().stage());f.time.addAndGet(30_000_000_000L);f.story.poll(f.c);single=f.ok(f.story.openVote(f.c,f.t1,()->true));f.ok(f.story.cast(f.c,f.t1,()->true,single.id(),"two"));assertEquals("open",f.story.cached(f.a).story().stage());}
    @Test void openRosterChangeCancelsAndReopensButClosedInputKeepsFrozenResult(){var f=new F();f.readyVote();var first=f.ok(f.story.openVote(f.c,f.t1,()->true));f.roster.remove(f.p2);f.story.rosterChanged(f.c);f.pump();var next=f.story.vote(f.a).orElseThrow();assertNotEquals(first.id(),next.id());f.bad(f.story.cast(f.c,f.t1,()->true,first.id(),"one"));
        f.store.delay=true;var save=f.story.cast(f.c,f.t1,()->true,next.id(),"one");f.pump();f.roster.clear();f.story.rosterChanged(f.c);assertEquals(SharedStory.Phase.PERSISTING,f.story.phase(f.a));assertEquals("vote",f.story.cached(f.a).story().stage());f.store.finish();assertEquals("one",f.ok(save).branches().get("vote").choice());assertTrue(f.story.cached(f.a).story().explorationOpen());assertEquals("NOT_IMPLEMENTED",f.story.effectStatus(f.a));}
    @Test void duplicateWrongRunAndExpiredVotesDoNotWrite(){var f=new F();f.readyVote();var v=f.ok(f.story.openVote(f.c,f.t1,()->true));f.ok(f.story.cast(f.c,f.t1,()->true,v.id(),"one"));int count=f.store.commits;f.bad(f.story.cast(f.c,f.t1,()->true,v.id(),"one"));f.bad(f.story.cast(f.d,f.t1,()->true,v.id(),"one"));f.bad(f.story.cast(f.c,f.t1,()->true,UUID.randomUUID(),"one"));assertEquals(count,f.store.commits);}
    @Test void unknownReceiptBlocksNewRequestsAndOnlyPositiveSameIdResolves(){var f=new F();f.readyVote();f.roster.remove(f.p2);f.story.rosterChanged(f.c);var v=f.ok(f.story.openVote(f.c,f.t1,()->true));f.store.unknown=true;f.bad(f.story.cast(f.c,f.t1,()->true,v.id(),"one"));assertEquals(SharedStory.Phase.RESULT_UNKNOWN,f.story.phase(f.a));f.bad(f.story.resolve(f.c));f.bad(f.story.advance(f.c,f.t1,()->true));assertEquals("vote",f.story.cached(f.a).story().stage());
        f.store.unknownAfter=true;f.store.save(f.c,f.store.request,()->true);assertEquals("open",f.ok(f.story.resolve(f.c)).story().stage());assertEquals("COMMITTED",f.story.vote(f.a).orElseThrow().state());}
    @Test void writeFailureHoldAndStaleGenerationKeepOldCacheAndOtherRun(){var f=new F();f.survey();f.store.fail=true;f.bad(f.story.advance(f.c,f.t1,()->true));assertEquals(SharedStory.Phase.HOLD,f.story.phase(f.a));assertNull(f.story.cached(f.a).story().stage());assertTrue(f.story.barrier(f.a).toCompletableFuture().isCompletedExceptionally());f.store.fail=false;f.ok(f.story.advance(f.d,f.t1,()->true));assertEquals("arrival",f.story.cached(f.b).story().stage());f.ok(f.story.refresh(f.c));f.store.delay=true;var work=f.story.advance(f.c,f.t1,()->true);f.pump();f.story.invalidate(f.a);f.store.finish();f.bad(work);assertNull(f.story.cached(f.a).story().stage());}
    @Test void regionAccessIsFailClosedUntilConfirmedOpenAndEffectsAreSeparate(){var f=new F();var access=new StoryAccess(f.story);assertFalse(access.entry(f.a,21,64,21));assertTrue(access.entry(f.a,1,64,1));f.readyVote();f.roster.remove(f.p2);f.story.rosterChanged(f.c);var v=f.ok(f.story.openVote(f.c,f.t1,()->true));f.story.effects((run,id,s)->{throw new IllegalStateException("controlled effect failure");});f.ok(f.story.cast(f.c,f.t1,()->true,v.id(),"one"));assertTrue(access.entry(f.a,21,64,21));assertFalse(access.entry(f.b,21,64,21));assertEquals("EFFECT_ERROR",f.story.effectStatus(f.a));assertEquals(SharedStory.Phase.READY,f.story.phase(f.a));}
    @Test void restrictedAcceptedQuestIsHiddenFromHUDAndDetailWithoutChangingState(){
        var f=new PersonalQuestTest.Fixture(true);var catalog=QuestCatalogTest.catalog();var journal=new QuestJournal(new QuestBatchTest.JournalStore(),f.quests,catalog,f.queue::add,()->{});
        var base=ExplorationView.empty();var hidden=new ExplorationView(true,base.regions(),base.places(),base.facts(),base.events(),base.members(),base.story(),base.conditions(),null,Set.of("survey_marker"),List.of());
        var states=Map.of("survey_marker",new QuestStore.Saved(QuestStore.Phase.ACTIVE,0),"path_marker",new QuestStore.Saved(QuestStore.Phase.NOT_ACCEPTED,-1));
        var view=new QuestJournal.View(states,new QuestJournalStore.Journal(Set.of("survey_marker"),new QuestJournalStore.Preferences(true,0),List.of()),hidden);
        assertTrue(journal.hudLines(view).isEmpty());assertTrue(QuestScreens.screen(catalog,view,"detail","survey_marker",0).stream().anyMatch(b->b.label().equals(QuestListView.UNAVAILABLE)));assertEquals(QuestStore.Phase.ACTIVE,view.states().get("survey_marker").phase());
    }
    @Test void restrictedAreaOverlapCannotLeakFromAnOutsideCorner(){var f=new F();var access=new StoryAccess(f.story);assertFalse(access.area(f.a,new QuestContent.Area(19,21,64,66,19,21)));assertTrue(access.area(f.a,new QuestContent.Area(1,3,64,66,1,3)));}
    @Test void requestFingerprintSeparatesFieldsEvenWithDelimiterText(){
        UUID id=UUID.randomUUID(),player=UUID.randomUUID();var one=new StoryStore.Request(id,1,"vote","open","t",true,"x","a/true/y/b",Set.of(player),Set.of("survey_marker"),List.of());
        var two=new StoryStore.Request(id,1,"vote","open","t/true/x/a",true,"y","b",Set.of(player),Set.of("survey_marker"),List.of());
        assertNotEquals(StoryStore.fingerprint(one),StoryStore.fingerprint(two));assertEquals(StoryStore.fingerprint(one),StoryStore.fingerprint(one));
    }
}
